*, *::before, *::after { box-sizing: border-box; }

.card {
  width: 300px;     /* total width, padding and border included */
  padding: 20px;
  border: 2px solid #ccc;
  margin: 16px;     /* space outside the border */
}

.menu a { color: blue; }   /* (0,1,1) */
#top a  { color: red; }    /* (1,0,1): wins for links inside #top */

.navbar {
  display: flex;
  justify-content: space-between;  /* logo left, links right */
  align-items: center;             /* vertically centered */
  gap: 1rem;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);  /* three equal columns */
  gap: 16px;
}
.gallery .featured { grid-column: 1 / 3; }  /* spans two columns */

/* Base: phones get one column */
.gallery { display: grid; grid-template-columns: 1fr; gap: 12px; }
img { max-width: 100%; height: auto; }

/* Tablets and up */
@media (min-width: 600px) {
  .gallery { grid-template-columns: repeat(2, 1fr); }
}

/* Desktops */
@media (min-width: 1000px) {
  .gallery { grid-template-columns: repeat(4, 1fr); }
}

